<section class="admin-page-head"><div><p class="admin-kicker">Clientes</p><h1>Detalle del cliente</h1><p>Consulta la información que usa tu equipo para identificar y atender a este cliente.</p></div></section>
<?php preg_match('/^./us',(string)$customer['legal_name'],$customerInitial) ?>
<section class="admin-panel customer-detail"><header><span class="customer-detail-mark" aria-hidden="true"><?= e($customerInitial[0]??'') ?></span><div><h2><?= e($customer['legal_name']) ?></h2><p><?= e($customer['code']) ?> · <?= e($customer['branch_name']) ?></p></div><span class="admin-status <?= (int)$customer['is_active']===1?'is-active':'is-danger' ?>"><?= (int)$customer['is_active']===1?'Activo':'Inactivo' ?></span></header>
<?php foreach(['Identificación'=>['customer_type'=>'Tipo de cliente','trade_name'=>'Nombre comercial','tax_identifier'=>'RFC o identificador fiscal','price_list_name'=>'Lista comercial'],'Comunicación'=>['email'=>'Correo','phone'=>'Teléfono','alternate_phone'=>'Teléfono alternativo'],'Contacto principal'=>['contact_name'=>'Nombre','contact_role'=>'Puesto','contact_phone'=>'Teléfono','contact_email'=>'Correo'],'Dirección principal'=>['address_line1'=>'Dirección','address_line2'=>'Referencia','city'=>'Ciudad','state_name'=>'Estado','postal_code'=>'Código postal']] as $heading=>$fields):?><section><h3><?= e($heading) ?></h3><dl><?php foreach($fields as $key=>$label):$display=$key==='customer_type'?($customer[$key]==='business'?'Empresa':'Persona'):($customer[$key]??'');?><div><dt><?= e($label) ?></dt><dd><?= e($display!==''&&$display!==null?$display:'Sin registrar') ?></dd></div><?php endforeach?></dl></section><?php endforeach?><?php if(!empty($customer['notes'])):?><section><h3>Observaciones comerciales</h3><p><?= e($customer['notes']) ?></p></section><?php endif?>
<div class="admin-head-actions"><?php if($capabilities['customers.edit']??false):?><a class="admin-primary-button" data-admin-form-link href="/admin/customers/edit?id=<?= e($customer['id']) ?>">Editar cliente</a><?php endif?><a class="admin-secondary-button" href="/admin/customers" data-admin-modal-cancel>Cerrar</a></div></section>
<section class="admin-panel customer-history"><h2>Actividad del cliente</h2><p>Consulta los cambios administrativos registrados para este cliente.</p><?php if(!$history):?><p>Todavía no hay actividad visible.</p><?php else:?><ul><?php foreach($history as $event):?><li><strong><?= e(['customer.create'=>'Cliente registrado','customer.update'=>'Datos actualizados','customer.status'=>'Cambio de estado'][$event['action']]??'Cambio administrativo') ?></strong><span><?= e($event['actor_name']??'Sistema') ?> · <?= e($event['created_at']) ?></span><small><?= e(['success'=>'Completado','failure'=>'No completado','denied'=>'Sin autorización'][$event['outcome']]??'Registrado') ?></small></li><?php endforeach?></ul><?php endif?></section>
